/** The terrain of grid cell (col, row), or null off the map. */
export function earthTerrain(col, row) {
  if (!Number.isInteger(col) || !Number.isInteger(row) || col < 0 || row < 0 || col >= EARTH.cols || row >= EARTH.rows) return null;
  return EARTH.codes[EARTH.grid[row][col]] || null;
}
/** The named region of a land cell ('' at sea). */
export function earthRegion(col, row) {
  if (col < 0 || row < 0 || col >= EARTH.cols || row >= EARTH.rows) return '';
  return EARTH.regionNames['0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'.indexOf(EARTH.regions[row][col])] || '';
}
/** Historical canal name for a strategic Earth isthmus cell ('' elsewhere). */
export function earthCanalName(col, row) {
  return EARTH.canals[`${col},${row}`] || '';
}
